INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 37, 'theory', 'Quiz: Tokio in practice');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 37, 0, 'What happens to the code after .await when the task is cancelled with abort()?', '["It runs to the end", "It does not run: the future is no longer polled and local values are destroyed", "Only the first statement runs", "The task restarts"]', 1, 'Cancellation in async is dropping the future; code after the nearest .await never runs, while Drop of the local variables does run.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 37, 1, 'What does cancelling a parent CancellationToken do?', '["Nothing", "It also cancels all children created with child_token()", "Only the parent", "It panics"]', 1, 'Cancelling the parent cascades to the child tokens; cancelling a child does not affect the parent.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 37, 2, 'How should you do cleanup that needs .await at shutdown?', '["Call .await inside Drop", "Move it into an explicit async close method called on normal shutdown", "Use unsafe", "Cleanup is impossible"]', 1, 'Drop is synchronous: you cannot wait in it. Slow cleanup is done with an explicit async method, and only quick actions are left in Drop.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 37, 3, 'What is it better to do with a request when the queue is full?', '["Accept it and wait forever", "Refuse quickly (load shedding), keeping responsiveness for accepted ones", "Double the queue", "Close the server"]', 1, 'A fast refusal does not pile up tasks and memory; accepted requests keep being served on time.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 37, 4, 'How do you run a heavy blocking computation without freezing the tokio worker threads?', '["Directly in an async fn", "tokio::task::spawn_blocking", "std::thread::sleep", "Through select!"]', 1, 'spawn_blocking runs the work in a separate thread pool, and the task waits for the result via .await.');
